attributes.visState:
{"title": "Visits: country → website → answer", "type": "vega", "aggs": [], "params": {"spec": "{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "title": {
  "text": "",
  "orient": "none"
 },
 "autosize": {
  "type": "fit",
  "contains": "padding"
 },
 "padding": 8,
 "signals": [
  {
   "name": "nodeW",
   "value": 14
  },
  {
   "name": "gap",
   "value": 8
  },
  {
   "name": "tot",
   "update": "data('total').length ? data('total')[0].v : 1"
  },
  {
   "name": "most",
   "update": "data('counts').length ? data('counts')[0].m : 1"
  },
  {
   "name": "unit",
   "update": "max(1, height - gap * (most - 1)) / max(tot, 1)"
  },
  {
   "name": "labelW",
   "value": 150
  },
  {
   "name": "hover",
   "value": "",
   "on": [
    {
     "events": "@band:mouseover",
     "update": "datum.skey + '>' + datum.tkey"
    },
    {
     "events": "@band:mouseout",
     "update": "''"
    }
   ]
  }
 ],
 "data": [
  {
   "name": "raw",
   "url": {
    "index": "logs-sentora-*",
    "body": {
     "size": 0,
     "query": {
      "bool": {
       "must": [
        "%dashboard_context-must_clause%",
        {
         "range": {
          "@timestamp": {
           "%timefilter%": true
          }
         }
        },
        {
         "term": {
          "sentora.log": "web-access"
         }
        },
        {
         "exists": {
          "field": "http.response.status_code"
         }
        }
       ],
       "must_not": [
        "%dashboard_context-must_not_clause%"
       ],
       "filter": [
        "%dashboard_context-filter_clause%"
       ]
      }
     },
     "aggs": {
      "a": {
       "terms": {
        "field": "source.geo.country_iso_code",
        "size": 10
       },
       "aggs": {
        "b": {
         "terms": {
          "field": "sentora.domain",
          "size": 8
         },
         "aggs": {
          "c": {
           "terms": {
            "field": "http.response.status_code",
            "size": 6
           }
          }
         }
        }
       }
      }
     }
    }
   },
   "format": {
    "property": "aggregations.a.buckets"
   }
  },
  {
   "name": "rows",
   "source": "raw",
   "transform": [
    {
     "type": "flatten",
     "fields": [
      "b.buckets"
     ],
     "as": [
      "bb"
     ]
    },
    {
     "type": "flatten",
     "fields": [
      "bb.c.buckets"
     ],
     "as": [
      "cc"
     ]
    },
    {
     "type": "formula",
     "as": "k0",
     "expr": "'' + datum.key"
    },
    {
     "type": "formula",
     "as": "k1",
     "expr": "'' + datum.bb.key"
    },
    {
     "type": "formula",
     "as": "k2",
     "expr": "'' + datum.cc.key"
    },
    {
     "type": "formula",
     "as": "n",
     "expr": "datum.cc.doc_count"
    },
    {
     "type": "filter",
     "expr": "datum.n > 0"
    }
   ]
  },
  {
   "name": "total",
   "source": "rows",
   "transform": [
    {
     "type": "aggregate",
     "fields": [
      "n"
     ],
     "ops": [
      "sum"
     ],
     "as": [
      "v"
     ]
    }
   ]
  },
  {
   "name": "c0",
   "source": "rows",
   "transform": [
    {
     "type": "aggregate",
     "groupby": [
      "k0"
     ],
     "fields": [
      "n"
     ],
     "ops": [
      "sum"
     ],
     "as": [
      "v"
     ]
    },
    {
     "type": "formula",
     "as": "col",
     "expr": "0"
    },
    {
     "type": "formula",
     "as": "name",
     "expr": "datum.k0"
    },
    {
     "type": "formula",
     "as": "key",
     "expr": "'0|' + datum.k0"
    }
   ]
  },
  {
   "name": "c1",
   "source": "rows",
   "transform": [
    {
     "type": "aggregate",
     "groupby": [
      "k1"
     ],
     "fields": [
      "n"
     ],
     "ops": [
      "sum"
     ],
     "as": [
      "v"
     ]
    },
    {
     "type": "formula",
     "as": "col",
     "expr": "1"
    },
    {
     "type": "formula",
     "as": "name",
     "expr": "datum.k1"
    },
    {
     "type": "formula",
     "as": "key",
     "expr": "'1|' + datum.k1"
    }
   ]
  },
  {
   "name": "c2",
   "source": "rows",
   "transform": [
    {
     "type": "aggregate",
     "groupby": [
      "k2"
     ],
     "fields": [
      "n"
     ],
     "ops": [
      "sum"
     ],
     "as": [
      "v"
     ]
    },
    {
     "type": "formula",
     "as": "col",
     "expr": "2"
    },
    {
     "type": "formula",
     "as": "name",
     "expr": "datum.k2"
    },
    {
     "type": "formula",
     "as": "key",
     "expr": "'2|' + datum.k2"
    }
   ]
  },
  {
   "name": "stacked",
   "source": [
    "c0",
    "c1",
    "c2"
   ],
   "transform": [
    {
     "type": "stack",
     "groupby": [
      "col"
     ],
     "field": "v",
     "sort": {
      "field": "v",
      "order": "descending"
     },
     "as": [
      "y0",
      "y1"
     ]
    },
    {
     "type": "window",
     "groupby": [
      "col"
     ],
     "sort": {
      "field": "v",
      "order": "descending"
     },
     "ops": [
      "row_number"
     ],
     "as": [
      "rank"
     ]
    }
   ]
  },
  {
   "name": "counts",
   "source": "stacked",
   "transform": [
    {
     "type": "aggregate",
     "groupby": [
      "col"
     ],
     "ops": [
      "count"
     ],
     "as": [
      "c"
     ]
    },
    {
     "type": "aggregate",
     "fields": [
      "c"
     ],
     "ops": [
      "max"
     ],
     "as": [
      "m"
     ]
    }
   ]
  },
  {
   "name": "nodes",
   "source": "stacked",
   "transform": [
    {
     "type": "formula",
     "as": "py0",
     "expr": "datum.y0 * unit + (datum.rank - 1) * gap"
    },
    {
     "type": "formula",
     "as": "py1",
     "expr": "datum.y1 * unit + (datum.rank - 1) * gap"
    },
    {
     "type": "formula",
     "as": "px",
     "expr": "labelW + datum.col * (width - nodeW - 2 * labelW) / 2"
    }
   ]
  },
  {
   "name": "sA",
   "source": "rows",
   "transform": [
    {
     "type": "aggregate",
     "groupby": [
      "k0",
      "k1"
     ],
     "fields": [
      "n"
     ],
     "ops": [
      "sum"
     ],
     "as": [
      "v"
     ]
    },
    {
     "type": "formula",
     "as": "skey",
     "expr": "'0|' + datum.k0"
    },
    {
     "type": "formula",
     "as": "tkey",
     "expr": "'1|' + datum.k1"
    },
    {
     "type": "formula",
     "as": "sname",
     "expr": "datum.k0"
    },
    {
     "type": "formula",
     "as": "tname",
     "expr": "datum.k1"
    }
   ]
  },
  {
   "name": "sB",
   "source": "rows",
   "transform": [
    {
     "type": "aggregate",
     "groupby": [
      "k1",
      "k2"
     ],
     "fields": [
      "n"
     ],
     "ops": [
      "sum"
     ],
     "as": [
      "v"
     ]
    },
    {
     "type": "formula",
     "as": "skey",
     "expr": "'1|' + datum.k1"
    },
    {
     "type": "formula",
     "as": "tkey",
     "expr": "'2|' + datum.k2"
    },
    {
     "type": "formula",
     "as": "sname",
     "expr": "datum.k1"
    },
    {
     "type": "formula",
     "as": "tname",
     "expr": "datum.k2"
    }
   ]
  },
  {
   "name": "bands",
   "source": [
    "sA",
    "sB"
   ],
   "transform": [
    {
     "type": "lookup",
     "from": "nodes",
     "key": "key",
     "fields": [
      "skey",
      "tkey"
     ],
     "as": [
      "sn",
      "tn"
     ]
    },
    {
     "type": "formula",
     "as": "trank",
     "expr": "datum.tn.rank"
    },
    {
     "type": "formula",
     "as": "srank",
     "expr": "datum.sn.rank"
    },
    {
     "type": "stack",
     "groupby": [
      "skey"
     ],
     "field": "v",
     "sort": {
      "field": "trank"
     },
     "as": [
      "so0",
      "so1"
     ]
    },
    {
     "type": "stack",
     "groupby": [
      "tkey"
     ],
     "field": "v",
     "sort": {
      "field": "srank"
     },
     "as": [
      "to0",
      "to1"
     ]
    },
    {
     "type": "formula",
     "as": "x1",
     "expr": "datum.sn.px + nodeW"
    },
    {
     "type": "formula",
     "as": "x2",
     "expr": "datum.tn.px"
    },
    {
     "type": "formula",
     "as": "xm",
     "expr": "(datum.x1 + datum.x2) / 2"
    },
    {
     "type": "formula",
     "as": "a0",
     "expr": "datum.sn.py0 + datum.so0 * unit"
    },
    {
     "type": "formula",
     "as": "a1",
     "expr": "datum.sn.py0 + datum.so1 * unit"
    },
    {
     "type": "formula",
     "as": "b0",
     "expr": "datum.tn.py0 + datum.to0 * unit"
    },
    {
     "type": "formula",
     "as": "b1",
     "expr": "datum.tn.py0 + datum.to1 * unit"
    },
    {
     "type": "formula",
     "as": "colorkey",
     "expr": "datum.sn.col == 0 ? datum.sname : datum.tname"
    },
    {
     "type": "formula",
     "as": "path",
     "expr": "'M' + datum.x1 + ',' + datum.a0 + 'C' + datum.xm + ',' + datum.a0 + ' ' + datum.xm + ',' + datum.b0 + ' ' + datum.x2 + ',' + datum.b0 + 'L' + datum.x2 + ',' + datum.b1 + 'C' + datum.xm + ',' + datum.b1 + ' ' + datum.xm + ',' + datum.a1 + ' ' + datum.x1 + ',' + datum.a1 + 'Z'"
    }
   ]
  }
 ],
 "scales": [
  {
   "name": "color",
   "type": "ordinal",
   "range": {
    "scheme": "tableau10"
   },
   "domain": {
    "fields": [
     {
      "data": "c0",
      "field": "name"
     },
     {
      "data": "c2",
      "field": "name"
     }
    ],
    "sort": true
   }
  }
 ],
 "marks": [
  {
   "type": "path",
   "name": "band",
   "from": {
    "data": "bands"
   },
   "encode": {
    "enter": {
     "path": {
      "field": "path"
     },
     "fill": {
      "scale": "color",
      "field": "colorkey"
     },
     "tooltip": {
      "signal": "datum.sname + ' \u2192 ' + datum.tname + ': ' + format(datum.v, ',')"
     }
    },
    "update": {
     "path": {
      "field": "path"
     },
     "fillOpacity": {
      "signal": "hover == datum.skey + '>' + datum.tkey ? 0.85 : 0.4"
     }
    }
   }
  },
  {
   "type": "rect",
   "from": {
    "data": "nodes"
   },
   "encode": {
    "update": {
     "x": {
      "field": "px"
     },
     "width": {
      "signal": "nodeW"
     },
     "y": {
      "field": "py0"
     },
     "y2": {
      "field": "py1"
     },
     "fill": {
      "signal": "datum.col == 1 ? '#4FA3F7' : scale('color', datum.name)"
     },
     "cornerRadius": {
      "value": 3
     },
     "tooltip": {
      "signal": "datum.name + ': ' + format(datum.v, ',')"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "nodes"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "datum.col == 0 ? datum.px - 6 : datum.col == 2 ? datum.px + nodeW + 6 : datum.px + nodeW + 6"
     },
     "y": {
      "signal": "(datum.py0 + datum.py1) / 2"
     },
     "baseline": {
      "value": "middle"
     },
     "align": {
      "signal": "datum.col == 0 ? 'right' : 'left'"
     },
     "fontSize": {
      "value": 12
     },
     "fontWeight": {
      "value": "bold"
     },
     "fill": {
      "signal": "datum.col == 1 ? '#4FA3F7' : scale('color', datum.name)"
     },
     "limit": {
      "signal": "labelW - 10"
     },
     "text": {
      "signal": "datum.py1 - datum.py0 > 9 ? datum.name + '  ' + format(datum.v, ',') : ''"
     }
    }
   }
  }
 ]
}"}}
